let language='ko';try{const saved=localStorage.getItem('paper-wind-language');language=saved==='ko'||saved==='en'?saved:(navigator.language.startsWith('ko')?'ko':'en');}catch{}
const originals=new WeakMap(),reverse=new Map(Object.entries(english).map(([ko,en])=>[en,ko]));
export const getLanguage=()=>language;
export function t(key,values={}){let text=language==='en'?(english[key]??key):key;return text.replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??`{${name}}`));}
function translatePage(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);for(let node=walker.nextNode();node;node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName))continue;let source=originals.get(node);if(!source){const text=node.data.trim(),key=english[text]?text:reverse.get(text);if(!key)continue;source={key,prefix:node.data.match(/^\s*/)[0],suffix:node.data.match(/\s*$/)[0]};originals.set(node,source);}node.data=source.prefix+t(source.key)+source.suffix;}document.documentElement.lang=language;document.title=language==='ko'?'종이와 바람 · Paper Wind Studio':'Paper & Wind · Paper Wind Studio';const editor=document.getElementById('editor');if(editor)editor.setAttribute('aria-label',t('종이 위에 접힘 선을 드래그하고 고정점을 찍는 편집 영역'));const picker=document.getElementById('language');if(picker)picker.value=language;}
export function setLanguage(next){if(!['ko','en'].includes(next))return;language=next;try{localStorage.setItem('paper-wind-language',next);}catch{}translatePage();window.dispatchEvent(new Event('paper-language-change'));}
export function initLanguage(){document.getElementById('language').addEventListener('change',event=>setLanguage(event.target.value));translatePage();}

